mapper.select:
SELECT count(*) totcnt FROM ttokssaemdb.user user, ttokssaemdb.branch branch WHERE user.branchid = branch.branchid
AND user.branchid = #{session_branchid}
AND user.username LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, user.userid, user.username, auth.auth_id, auth.auth, user.contact, user.email, user.useyn, DATE_FORMAT(user.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.user user, ttokssaemdb.branch branch, ttokssaemdb.cmm_auth auth
AND user.branchid = branch.branchid AND user.auth_id = auth.auth_id
AND user.branchid = #{session_branchid}
AND user.username LIKE #{likeQuery}
user.userid user.username user.auth_id user.contact user.email user.useyn user.regdate ASC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

